<script setup lang="ts">
import{computed,onBeforeUnmount,onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{enterpriseApi,selectTenant,type TenantContext}from'@/api/enterprise';import{multimodalApi as api}from'@/api/multimodal'
const tab=ref('library'),loading=ref(true),busy=ref(false),ctx=ref<TenantContext|null>(null),cap=ref<any>({}),assets=ref<any[]>([]),selected=ref<any>(),mediaUrl=ref(''),frameUrl=ref(''),streams=ref<any[]>([]),stream=ref<any>(),updates=ref<any[]>([]),doc=ref<any>(),socket=ref<WebSocket>(),online=ref(1),conflict=ref<any>(),file=ref<File>()
const form=reactive({copyright:'unknown',license:'',source:'',consent:false,location:''}),live=reactive({name:'',text:'',type:'observation'}),edit=reactive({resource_type:'report',resource_id:'',path:'/content_markdown',value:'',comment:'',client:`web-${crypto.randomUUID()}`,sequence:1}),tabs=[['library','媒体库'],['capture','移动采集'],['evidence','证据查看器'],['live','实时情报'],['collab','协作空间'],['safety','安全与版权'],['quality','模型与质量']]
const can=(p:string)=>ctx.value?.permissions.includes(p),kind=computed(()=>selected.value?.media_type)
async function load(){loading.value=true;try{ctx.value=await enterpriseApi.context();selectTenant(ctx.value.organization.id,ctx.value.workspaces[0]?.id);[cap.value,assets.value,streams.value]=await Promise.all([api.capabilities(),api.assets(),api.streams()])}finally{loading.value=false}}
function choose(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]}
async function upload(){if(!file.value)return ElMessage.warning('请选择媒体');busy.value=true;try{const d=new FormData();d.append('file',file.value);d.append('workspace_id',ctx.value?.workspaces[0]?.id||'');d.append('copyright_status',form.copyright);d.append('license_name',form.license);d.append('source_url',form.source);d.append('consent_confirmed',String(form.consent));d.append('capture_metadata',JSON.stringify({location:form.location,captured_at:new Date().toISOString(),user_agent:navigator.userAgent}));await api.upload(d);await load();tab.value='library';ElMessage.success('已进入真实处理队列')}finally{busy.value=false}}
async function openAsset(id:string){if(mediaUrl.value)URL.revokeObjectURL(mediaUrl.value);selected.value=await api.asset(id);try{mediaUrl.value=await api.content(`/api/v1/multimodal/assets/${id}/content`)}catch{mediaUrl.value=''}tab.value='evidence'}
async function locate(e:any){if(frameUrl.value)URL.revokeObjectURL(frameUrl.value);frameUrl.value=e.content_url?await api.content(e.content_url):'';if(e.start_ms!=null){const el=document.querySelector('.stage audio,.stage video')as HTMLMediaElement;if(el){el.currentTime=e.start_ms/1000;void el.play()}}}
async function remove(id:string){await ElMessageBox.confirm('原件、抽帧和证据将同时删除。','确认删除');await api.remove(id);selected.value=null;await load()}
async function createStream(){stream.value=await api.createStream({name:live.name,source_type:'field',workspace_id:ctx.value?.workspaces[0]?.id});live.name='';await load()}
async function openStream(s:any){stream.value=s;updates.value=await api.updates(s.id)}async function postUpdate(){await api.addUpdate(stream.value.id,{update_type:live.type,payload:{text:live.text}});live.text='';updates.value=await api.updates(stream.value.id)}
async function openDoc(){doc.value=await api.openDoc({resource_type:edit.resource_type,resource_id:edit.resource_id,workspace_id:ctx.value?.workspaces[0]?.id});connect()}
async function refresh(){doc.value=await api.doc(doc.value.id)}
async function connect(){socket.value?.close();const t=await api.ticket(doc.value.id),protocol=location.protocol==='https:'?'wss':'ws';const ws=new WebSocket(`${protocol}://${location.host}/api/v1/multimodal/ws/collaboration/${doc.value.id}?ticket=${encodeURIComponent(t.ticket)}`);socket.value=ws;ws.onopen=()=>ws.send(JSON.stringify({type:'presence',cursor:'document'}));ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.type==='presence')online.value=2;if(m.type?.startsWith('change.')||m.type==='comment.created')void refresh();if(m.type==='change.conflict')conflict.value=m}}
async function save(){const r=await api.change(doc.value.id,{base_version:doc.value.version,client_id:edit.client,client_sequence:edit.sequence++,operations:[{op:'set',path:edit.path,value:edit.value}]});if(r.conflict)conflict.value=r;await refresh()}async function comment(){await api.comment(doc.value.id,{body:edit.comment,anchor:{path:edit.path},mention_user_ids:[]});edit.comment='';await refresh()}async function resolve(strategy:string){await api.resolve(conflict.value.change_id,{strategy,operations:[]});conflict.value=null;await refresh()}
onMounted(load);onBeforeUnmount(()=>{socket.value?.close();[mediaUrl.value,frameUrl.value].filter(Boolean).forEach(URL.revokeObjectURL)})
</script>
<template><main class="page"><header><div><small>MULTIMODAL INTELLIGENCE</small><h1>多模态情报与实时协同</h1><p>从原始媒体到可定位证据，并在组织边界内实时协作。</p></div><div class="health"><span :class="{ok:cap.vision_configured}">视觉 {{cap.vision_configured?'可用':'未配置'}}</span><span :class="{ok:cap.transcription_configured}">转写 {{cap.transcription_configured?'可用':'未配置'}}</span></div></header><nav><button v-for="x in tabs" :class="{active:tab===x[0]}" @click="tab=x[0]">{{x[1]}}</button></nav><div v-if="loading" class="empty">正在加载媒体工作区...</div><template v-else>
<section v-if="tab==='library'"><div class="head"><div><h2>媒体库</h2><p>内容哈希去重；图片同时检测视觉重复。</p></div><button @click="tab='capture'">上传媒体</button></div><div v-if="!assets.length" class="empty">尚无真实媒体。上传后才会显示证据。</div><div class="grid"><article v-for="x in assets" @click="openAsset(x.id)"><b>{{x.media_type.toUpperCase()}}</b><strong>{{x.filename}}</strong><span>{{(x.byte_size/1048576).toFixed(2)}} MB · {{x.status}}</span><small>{{x.safety_status}}</small><i v-if="x.duplicate_of_id">视觉重复</i></article></div></section>
<section v-else-if="tab==='capture'"><h2>移动采集与上传</h2><p>手机可调用相机或媒体库。音视频必须确认授权。</p><label class="drop"><input type="file" accept="image/*,audio/*,video/*" capture="environment" @change="choose"><strong>{{file?.name||'选择或现场采集媒体'}}</strong><span>图片、音频或视频</span></label><div class="form"><label>版权状态<select v-model="form.copyright"><option>unknown</option><option>owned</option><option>licensed</option><option>fair_use</option></select></label><label>许可名称<input v-model="form.license"></label><label>来源链接<input v-model="form.source" type="url"></label><label>现场位置<input v-model="form.location" placeholder="可选，不自动读取定位"></label><label class="check"><input v-model="form.consent" type="checkbox">已获得音视频采集与分析授权</label><button :disabled="busy" @click="upload">{{busy?'上传中':'上传并处理'}}</button></div></section>
<section v-else-if="tab==='evidence'"><div v-if="!selected" class="empty">从媒体库选择内容查看证据。</div><template v-else><div class="head"><div><h2>{{selected.filename}}</h2><p>{{selected.status}} · {{selected.error_message||'真实处理记录'}}</p></div><span><button v-if="selected.status==='failed'" @click="api.retry(selected.id).then(()=>openAsset(selected.id))">重试</button><button v-if="can('media.manage')" class="danger" @click="remove(selected.id)">删除</button></span></div><div class="viewer"><div class="stage"><img v-if="kind==='image'&&mediaUrl" :src="mediaUrl"><audio v-else-if="kind==='audio'&&mediaUrl" :src="mediaUrl" controls/><video v-else-if="kind==='video'&&mediaUrl" :src="mediaUrl" controls/><img v-if="frameUrl" class="frame" :src="frameUrl"><p v-if="!mediaUrl">媒体不可预览或受策略限制。</p></div><aside><h3>逐条证据</h3><button v-for="e in selected.evidence" @click="locate(e)"><strong>{{e.type}}</strong><span>{{e.start_ms!=null?(e.start_ms/1000).toFixed(1)+'s':e.frame_number?'帧 '+e.frame_number:e.bbox?.length?'区域 '+e.bbox.join(', '):'整项'}}</span><p>{{e.text}}</p></button><div v-if="!selected.evidence.length" class="empty">没有证据。模型缺失或处理失败时不会生成模拟结果。</div></aside></div></template></section>
<section v-else-if="tab==='live'"><div class="split"><div><h2>直播流与现场更新</h2><form @submit.prevent="createStream"><input v-model="live.name" required placeholder="现场事件名称"><button>创建实时流</button></form><button v-for="s in streams" class="row" @click="openStream(s)"><strong>{{s.name}}</strong><span>{{s.status}} · {{new Date(s.started_at).toLocaleString()}}</span></button></div><div v-if="stream"><h3>{{stream.name||'实时更新'}}</h3><form @submit.prevent="postUpdate"><select v-model="live.type"><option>observation</option><option>transcript</option><option>risk</option><option>location</option><option>status</option></select><input v-model="live.text" required placeholder="已核实的更新"><button>发布</button></form><ol><li v-for="x in updates"><b>#{{x.sequence}} {{x.type}}</b><span>{{x.payload.text}}</span></li></ol></div></div></section>
<section v-else-if="tab==='collab'"><div v-if="!doc"><h2>打开报告或工作流协作空间</h2><form @submit.prevent="openDoc"><select v-model="edit.resource_type"><option>report</option><option>workflow</option></select><input v-model="edit.resource_id" required placeholder="资源 ID"><button>开始协作</button></form></div><template v-else><div class="head"><div><h2>协作文档 v{{doc.version}}</h2><p>{{doc.resource_type}} · 在线 {{online}}</p></div><button @click="connect">重新连接</button></div><div class="collab"><div><pre>{{JSON.stringify(doc.snapshot,null,2)}}</pre><label>受控字段路径<input v-model="edit.path"></label><label>新值<textarea v-model="edit.value"/></label><button @click="save">提交版本变更</button></div><aside><h3>评论</h3><article v-for="x in doc.comments"><strong>{{x.user_id.slice(0,8)}}</strong><p>{{x.body}}</p></article><textarea v-model="edit.comment" placeholder="评论"></textarea><button @click="comment">发表评论</button></aside></div><div v-if="conflict" class="conflict"><strong>检测到版本冲突</strong><p>同一路径已由其他成员修改。</p><button @click="resolve('keep_server')">保留服务器版本</button><button class="danger" @click="resolve('apply_client')">应用客户端变更</button></div></template></section>
<section v-else-if="tab==='safety'"><h2>版权、隐私与内容安全</h2><div class="policies"><article><strong>授权审查</strong><p>未确认授权的音视频进入人工复核。</p></article><article><strong>敏感信息</strong><p>PII 命中不会自动公开。</p></article><article><strong>彻底删除</strong><p>原件、抽帧、证据和引用同步清除。</p></article></div><div class="rows"><div v-for="x in assets"><strong>{{x.filename}}</strong><span>{{x.copyright_status}} · {{x.safety_status}}</span><button v-if="can('media.manage')" @click="api.safety(x.id,{decision:'approved',note:'已人工复核版权、授权和敏感信息'}).then(load)">批准</button></div></div></section>
<section v-else><h2>模型路由、成本与质量</h2><div class="metrics"><article><span>视觉模型</span><strong>{{cap.vision_configured?'可用':'缺少配置'}}</strong></article><article><span>转写模型</span><strong>{{cap.transcription_configured?'可用':'缺少配置'}}</strong></article><article><span>文件上限</span><strong>{{cap.max_file_mb}} MB</strong></article><article><span>模拟结果</span><strong>禁止</strong></article></div><p class="notice">模型选择受租户路由和月度预算约束。失败保留真实诊断，不伪造 OCR、字幕或说话人。</p></section>
</template></main></template>
<style scoped>.page{min-height:100vh;padding:30px;background:#f4f6f5;color:#17231f}.page>header,.head{display:flex;justify-content:space-between;align-items:end;gap:20px}.page h1{font-size:31px;margin:5px 0}.page h2{font-size:20px}.page p{color:#66736d}.page>header small{color:#147267;font-weight:800}.health{display:flex;gap:8px}.health span{padding:7px 9px;background:#f3dfdc;color:#8b3439}.health .ok{background:#dcece5;color:#146659}nav{display:flex;overflow:auto;border-bottom:1px solid #cbd5d1;margin:24px 0}nav button{white-space:nowrap;background:none;border:0;padding:12px 14px}nav .active{color:#126d63;border-bottom:2px solid #126d63}.head>button,form button,.form>button,.collab button{background:#176f67;color:white}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:#d6dfdb;border:1px solid #d6dfdb}.grid article{position:relative;display:grid;gap:8px;min-height:140px;padding:16px;background:#fff;cursor:pointer}.grid article b{font-size:11px;color:#137065}.grid article i{position:absolute;right:8px;top:8px;background:#fff0cf;padding:3px;font-style:normal}.drop{display:grid;place-items:center;gap:8px;min-height:180px;border:1px dashed #7c9188;background:#fff;cursor:pointer}.drop input{position:absolute;opacity:0}.form{display:grid;grid-template-columns:1fr 1fr;gap:12px;max-width:800px;margin-top:16px}.form label,.collab label{display:grid;gap:5px}.form .check{display:flex;align-items:center;gap:8px}.viewer{display:grid;grid-template-columns:2fr minmax(320px,1fr);border:1px solid #ccd6d2;min-height:500px}.stage{display:grid;place-items:center;position:relative;background:#17201d;padding:16px}.stage img,.stage video{max-width:100%;max-height:70vh}.stage audio{width:90%}.stage .frame{position:absolute;right:12px;bottom:12px;width:180px;border:2px solid white}.viewer aside{overflow:auto;max-height:70vh;background:white}.viewer aside h3{padding:0 14px}.viewer aside button{display:block;width:100%;text-align:left;padding:12px;border:0;border-top:1px solid #e0e6e3;background:white}.viewer aside button span{float:right}.split,.collab{display:grid;grid-template-columns:1fr 1fr;gap:24px}form{display:flex;gap:8px;margin:12px 0}.row{display:flex;justify-content:space-between;width:100%;padding:12px;border:0;border-bottom:1px solid #d2dcd7;background:none}.collab pre{max-height:390px;overflow:auto;padding:14px;background:#18231f;color:#e4eee9}.collab textarea{min-height:90px}.conflict{position:fixed;right:24px;bottom:24px;max-width:420px;padding:18px;background:#fff;border-left:4px solid #a93d45;box-shadow:0 8px 30px #0003}.policies,.metrics{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid #d4ddd9}.policies article,.metrics article{padding:16px;background:#fff;border-right:1px solid #d4ddd9}.metrics span,.metrics strong{display:block}.metrics strong{font-size:20px}.rows>div{display:grid;grid-template-columns:1fr 1fr auto;gap:12px;padding:12px;border-bottom:1px solid #d2dcd7}.notice{padding:13px;border-left:3px solid #197268;background:#e6f1ed}.danger{background:#a13b43!important;color:#fff}input,select,textarea{min-width:0;padding:10px;border:1px solid #bac8c2;border-radius:4px;background:#fff}button{border:0;border-radius:4px;padding:9px 12px;background:#e0e9e5;cursor:pointer}.empty{padding:55px;text-align:center;color:#6c7873}@media(max-width:900px){.grid,.metrics{grid-template-columns:1fr 1fr}.viewer,.split,.collab{grid-template-columns:1fr}}@media(max-width:600px){.page{padding:76px 12px 24px}.page>header{display:block}.health{margin-top:12px}.grid,.form,.policies,.metrics{grid-template-columns:1fr}.viewer{min-height:0}.stage{min-height:250px}form{display:grid}.conflict{left:12px;right:12px;bottom:12px}}</style>
